{
  "root_causes": [
    {
      "service": "recommendation",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, attr_status_code, attr_http_response_status_code, count(*) n FROM abnormal_traces WHERE service_name='frontend' AND span_name='HTTP /recommendations' GROUP BY ALL",
          "claim": "All 171 frontend /recommendations server spans in the incident period returned HTTP 500 with Error status."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'normal' p, count(*) n FROM normal_traces WHERE service_name='recommendation' AND attr_span_kind='Server' UNION ALL SELECT 'abnormal', count(*) FROM abnormal_traces WHERE service_name='recommendation' AND attr_span_kind='Server'",
          "claim": "Recommendation served 115 server spans before the incident and none during it."
        },
        {
          "kind": "metric",
          "sql": "SELECT 'normal' p, count(*) n FROM normal_metrics_sum WHERE service_name='recommendation' AND attr_k8s_pod_name='recommendation-69bf88479c-jwhg7' UNION ALL SELECT 'abnormal', count(*) FROM abnormal_metrics_sum WHERE service_name='recommendation' AND attr_k8s_pod_name='recommendation-69bf88479c-jwhg7'",
          "claim": "The recommendation pod's uptime and CPU metrics appear before the incident and disappear entirely during it."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, level, message, count(*) n FROM abnormal_logs WHERE service_name='frontend' AND level='ERROR' GROUP BY ALL",
          "claim": "Frontend logged 'Recommendation service failed' at ERROR level 56 times during the incident."
        }
      ]
    },
    {
      "service": "profile",
      "fault_kind": "wrong_return_value",
      "evidence": [
        {
          "kind": "log",
          "sql": "SELECT service_name, message, count(*) n FROM abnormal_logs WHERE service_name='profile' GROUP BY ALL ORDER BY n DESC",
          "claim": "Profile logged 'hotel_count=0' and 'profiles_returned=0' for 86 requests while returning almost no hotels."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'normal' p, span_name, count(*) n, round(avg(duration)/1e6,3) avg_ms FROM normal_traces WHERE service_name='profile' AND span_name='memcached_get_profile' GROUP BY ALL UNION ALL SELECT 'abnormal', span_name, count(*), round(avg(duration)/1e6,3) FROM abnormal_traces WHERE service_name='profile' AND span_name='memcached_get_profile' GROUP BY ALL",
          "claim": "Profile's memcached_get_profile spans dropped from about 93us average to about 8us, with no error status."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, count(*) n, round(avg(duration)/1e6,3) avg_ms FROM abnormal_traces WHERE service_name='frontend' AND span_name='HTTP /hotels' OR span_name='profile.Profile/GetProfiles' GROUP BY ALL",
          "claim": "Frontend /hotels requests still succeed with 200 but their profile lookups return quickly and empty."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "recommendation",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.span_name, c.attr_status_code, count(*) n FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='frontend' AND c.span_name='recommendation.Recommendation/GetRecommendations' GROUP BY ALL",
          "claim": "Frontend's client calls to recommendation's GetRecommendations are the failing hop behind the frontend 500s."
        }
      ]
    },
    {
      "from": "profile",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.span_name, count(*) n, round(avg(c.duration)/1e6,3) avg_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='frontend' AND c.service_name='profile' GROUP BY ALL",
          "claim": "Frontend's calls into profile.Profile/GetProfiles return fast during the incident, consistent with empty profile data reaching the user's hotel search."
        }
      ]
    }
  ]
}
